INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Concealed Intent', 'Concealed Intent is a simultaneous turn-based game of tactical space combat. Players control their ships in a fully 3D world - hunting down their enemies, just as they are being hunted themselves. In Concealed Intent you know your enemies are out there, but not exactly where, or even what they are.' FROM games WHERE igdb_id = 35142 ON CONFLICT (game_id, language_code) DO NOTHING;
