INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doctor Watson - Treasure Island', 'Players will experience an exciting adventure as Dr. Watson at fantastic locations. The first part of this new 3D hidden object series takes players to the famous Treasure Island. In this adventure, players solve exciting puzzles and interact with a varied landscape and many locations. As a special bonus, the adventure can be played with 3-D glasses in real 3D. But even without 3D glasses an addictive Hidden Object game awaits the player.' FROM games WHERE igdb_id = 33442 ON CONFLICT (game_id, language_code) DO NOTHING;
