INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghostbusters: Slime City', 'New York City has been overrun by paranormal activity and its up to you as a new Ghostbusters recruit to save the city and humanity as we know it! Those ghosts and demons don’t know what they’re in for! Grab your Proton Pack and build your own Ghostbusters team in Manhattan, blasting and trapping ghosts for amazing rewards! Stand strong, don’t cross the streams, and work your way to becoming the ultimate ghostbusting team.' FROM games WHERE igdb_id = 96751 ON CONFLICT (game_id, language_code) DO NOTHING;
