INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robert Mensah''s Sins of the Father', 'Sins Of The Father is a small adventure game. You play Tim, a twelve year old going thirteen who has to go looking for his father in Hell after discovering an old chest with some specific items in it. Travel through Tim''s interpretation of Hell. Enjoy this little wave based system game with end scene bosses.This is a very simple game with basic game mechanics, physics and AI. Hope you enjoy the trailers and images.' FROM games WHERE igdb_id = 33287 ON CONFLICT (game_id, language_code) DO NOTHING;
