INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Solar: Chaos War', 'Introducing Blue Solar: Chaos War, a roguelike sci-fi space adventure. Become a trader, pirate, adventurer and more. Shape a randomly generated universe. Invest in economies, engage in war, and compete for planets for your chosen government. Unite the universe, or lay waste to it all.' FROM games WHERE igdb_id = 32057 ON CONFLICT (game_id, language_code) DO NOTHING;
