INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Powerpuff Girls: Flipped Out', 'It''s not a hybrid game—it''s two awesome ways to play! Flip to SUGAR mode and use your wits to match same colored creatures until they explode. Or flip to SPICE mode and use your fists to battle the beasts in hand-to-hand combat. It''s like two games in one!' FROM games WHERE igdb_id = 90373 ON CONFLICT (game_id, language_code) DO NOTHING;
