INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Living Legends: Bound by Wishes', 'Your husband Jack travelled back to the town of Wishville to fulfill a long-standing debt, and assured you he wouldn’t be gone for too long. But when he doesn’t come home after a few days, you follow in his footsteps to find out what happened. Upon arriving at the town though, you discover this place isn’t the dream come true that it once was. It’s now turned into an absolute nightmare!' FROM games WHERE igdb_id = 94880 ON CONFLICT (game_id, language_code) DO NOTHING;
