INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moonlight', 'Moonlight is a short game, about a little character named Kinubo and his quest to the moon! Kinubo finds himself in a new village while looking for help on his quest, but most don''t accept his presence. The characters here are a very tight bunch, and they don''t take kindly to strangers! You must earn their acceptance, and the only way you''ll ever make it to the moon, is to win them over one by one!' FROM games WHERE igdb_id = 33711 ON CONFLICT (game_id, language_code) DO NOTHING;
