INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Jones VR', 'Space Jones is a FPS VR game. Story: At an era of human space colony expansion, a bounty hunter (the player) accidently picked up a mysterious treasure named “Star Box”. Therefore, the bounty hunter has been targeted by multiple space pirates. A major war will be triggered at any time. The player will have no choice but to eliminate all the pirate battleships in flocks.' FROM games WHERE igdb_id = 31816 ON CONFLICT (game_id, language_code) DO NOTHING;
