INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Agency: Chapter 1', 'The Agency is an episodic mystery kinetic novel. In a fictional dystopic sci-fi steampunk world still recovering from the destruction of a recent global war; a young man travels to the Imperial capital city to seek better fortunes for himself. Upon his arrival he is recruited in a private investigators agency and is soon embroiled in a case that will change his life forever!' FROM games WHERE igdb_id = 32353 ON CONFLICT (game_id, language_code) DO NOTHING;
