INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bullet Train', 'Bullet Train is a shooter designed for use virtual reality technology to immerse players in intense combat scenarios. Players have amazing abilities such as teleportation (zip around the map and confuse enemies with sneak attacks,) slow-motion (slow down the action and make precise moves before time catches up to you,) and bullet-catching (grab projectiles out of the air and throw them back at enemies) that give them the edge in battle.' FROM games WHERE igdb_id = 20455 ON CONFLICT (game_id, language_code) DO NOTHING;
