INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cubicolor', 'Cubicolor is a minimalist puzzle game. The rules are simple: Match the color patches on the board and reach the exit, all on one single path. The game gets harder as the levels progress, always accompanying you with soothing piano tunes.' FROM games WHERE igdb_id = 33430 ON CONFLICT (game_id, language_code) DO NOTHING;
