INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Entschuldigung', 'Entschuldigung (which means ‘sorry’ in German) is a bleak horror story, told by a lost young man who longs to find a place in which he can feel safe. Set in pre-war Berlin, the story is driven by an insatiable curiosity that leads our protagonist down a very dark path into the unknown. As he fights to make sense of his reality, he is also fighting to make sense of himself.' FROM games WHERE igdb_id = 30087 ON CONFLICT (game_id, language_code) DO NOTHING;
