INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kuboom', 31738, '2016-07-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co978n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hz7u1lcik93qnoiyux2d.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kuboom', 'Choose a character and customize it. Get a firearm and show the enemies, who’s the boss of the battlefield. In this multiplayer game, you can find almost any weapon: pistol, shotgun, machine gun, or a sniper rifle. Choosing the weapon, pay attention to its stats: each piece varies by damage and accuracy. Get the weapon that suits you best. All weapons in the game can be customized and upgraded: change the barrel to improve the shooting ability, add a trinket or set a scope to shoot like a true sniper. You can also choose among the common, rare, legendary and exotic weapon skins one that will reflect your personality. If it comes to a close combat, use a knife. The game has any kind of blades: from a butterfly knife to a machete. And for those who want to surprise their enemy in a short fight, there is an axe or even a shovel.' FROM games WHERE igdb_id = 31738 ON CONFLICT (game_id, language_code) DO NOTHING;
