INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Peter Panic', 'Peter Panic is the world''s first mobile mini-game musical, bringing all the magic of Big Broadway to your smart devices! Peter is an aspiring young director who wants to bring theater back to his hometown. As he travels from one strange location to the next, he must perform dozens of challenging, weird mini games to convince as many people as he can to help him. Boasting a full slate of original songs performed by an amazing cast of Broadway talent (including Tony nominees) and a full score by award-winning composer Benjamin Bonnema, this mobile musical experience by James Marion will have you begging for an encore.' FROM games WHERE igdb_id = 24055 ON CONFLICT (game_id, language_code) DO NOTHING;
