INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mini Mario & Friends: Amiibo Challenge', 'In the free-to-play game Mini Mario and Friends Amiibo Challenge, Tap an amiibo figure on the Wii U GamePad controller or New Nintendo 3DS system (or to a Nintendo 3DS, Nintendo 3DS XL or Nintendo 2DS system using the Nintendo 3DS NFC Reader/Writer accessory) to guide one of 11 minis across more than 60 levels. Players can tap any compatible amiibo figure. Or, by tapping specific amiibo figures, players can guide minis that have exclusive level sets or their own unique abilities, like mini Mario’s wall jump or mini Yoshi, who can eat enemies.' FROM games WHERE igdb_id = 18195 ON CONFLICT (game_id, language_code) DO NOTHING;
