INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sethian', 'Sethian is a sci-fi puzzle game in which you master a fictitious language. An archaeologist in the distant future, you venture to the far-flung planet of Sethian, investigating the mysterious disappearance of the people there centuries ago. An abandoned computer may have the answers you seek, but it only operates in the lost native language. Master their language, unravel their mysteries, and challenge their philosophy.' FROM games WHERE igdb_id = 26160 ON CONFLICT (game_id, language_code) DO NOTHING;
