INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Strike Vector EX', 'Strike Vector EX is a competitive first-person aerial-combat game that satisfies every gamer’s dream of waging dizzying dogfights with super-powered aircraft. Bursting with mech-inspired ships, Ragequit’s game brings a story-based single-player campaign to consoles complete with characters, cutscenes and deadly AI.' FROM games WHERE igdb_id = 22798 ON CONFLICT (game_id, language_code) DO NOTHING;
