INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Huntsman: Winter''s Curse', 'Winter is fast approaching as Queen Freya''s army marches relentlessly on the White Lands. Beneath the shadow of that deadly war Elisabeth’s quiet life on her family''s farm in Vardhelm comes to an abrupt end as she embarks on a journey of her own. Join her on a quest to find her missing brothers as you explore an expanded Huntsman universe, one where you''ll encounter both familiar faces and new dangers, all while discovering the secret Elisabeth herself unknowingly carries.' FROM games WHERE igdb_id = 22813 ON CONFLICT (game_id, language_code) DO NOTHING;
