INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Day R Survival', 'Can you survive in a world destroyed by nuclear war? With radiation, hunger and disease all around you. You have to cross the entire country and save your family. Who knows if they are even alive, or if radiation and the deadly virus have already reached them? Uncover the secret of the apocalypse and regain your memories during a journey across the huge territory of the USSR in the 1980s.' FROM games WHERE igdb_id = 175678 ON CONFLICT (game_id, language_code) DO NOTHING;
