INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Rats', '“Dungeon Rats, named after the 7th Heavy Armored Division of the Imperial Guards, is a turn-based, party-based dungeon crawler set in the Age of Decadence world. It''s an RPG focused almost exclusively on combat for players who like turn-based combat in general and AoD combat in particular, so if you want to fight your way out of a prison mine (or die trying) you''ve come to the right place.”' FROM games WHERE igdb_id = 25208 ON CONFLICT (game_id, language_code) DO NOTHING;
