INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Kingdom', 'Islands sometimes appear out of the blue in the clouds. The mysterious Pocket Kingdom is one of them. Wander around its districts, solve puzzles and listen to the weird stories told by the locals. Unveiling the place''s mysteries depends on it. So does getting out of it.' FROM games WHERE igdb_id = 32991 ON CONFLICT (game_id, language_code) DO NOTHING;
