INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Rose Valkyrie', '"Defend humanity from the Chimera Virus as the new leader of Japan’s covert military agency (ACID) in Dark Rose Valkyrie! Featuring work from “Tales of” scenario writer Takumi Miyajima and “Tales of” character designer Kosuke Fujishima, this real-time combat, action-packed RPG will have you battling enemies that change in form and strength as darkness sets. But that’s not all, a traitor is in your midst! Use a visual-novel interview system to find them out and strengthen the Valkyrie Force and save the world!"' FROM games WHERE igdb_id = 25746 ON CONFLICT (game_id, language_code) DO NOTHING;
